ALTER TABLE "books" ADD COLUMN "state" text DEFAULT 'scanned' NOT NULL;--> statement-breakpoint
CREATE INDEX "idx_books_shelved" ON "books" USING btree ("shelf_range","sort_key") WHERE "state" = 'shelved';--> statement-breakpoint
ALTER TABLE "books" ADD CONSTRAINT "books_state_check" CHECK ("state" IN ('scanned', 'unidentified', 'identified', 'shelved', 'checked_out', 'withdrawn', 'discarded'));--> statement-breakpoint
CREATE VIEW "public"."shelved_books" AS (select "id", "isbn13", "isbn10", "title", "subtitle", "authors", "publisher", "published", "pages", "notes", "shelf_range", "is_fiction", "classification_source", "classification_confidence", "author_filing", "series_name", "series_index", "title_filing", "sort_key", "location", "lookup_source", "front_image", "back_image", "edge_image", "cover_image", "cover_checked_at", "front_hash", "cover_hash", "front_crop", "back_crop", "edge_crop", "cropped", "isbn_source", "ocr_text", "scanned_at", "shelved_at", "checked_out_at", "state" from "books" where "books"."state" = 'shelved');